package validator

// validator_windows_sh_missing_rule.go — windows_sh_missing rule
//
// REQ-IMP-9 (REQ-2026-11-15, ML-3D): when GOOS is "windows" and `sh` is not
// found in PATH, emit a WARNING (never a violation) listing every .sh
// convenience artifact generated by `trackfw init` that is present on disk.
//
// Guards (trackfw guard ...) are Go subcommands and are explicitly excluded:
// they execute without sh and do not need a POSIX shell.
//
// No build tag — the rule file is compiled on every platform. The GOOS guard
// is runtime (via CurrentGOOS) so tests can inject "windows" on macOS/Linux.

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// shConvenienceArtifacts is the exhaustive list of .sh files that `trackfw init`
// may generate and that require the user to have a POSIX shell in their
// interactive PATH to execute.
//
// Two classes of artifacts are explicitly excluded:
//   - Guards (trackfw-credential-guard.sh, trackfw-git-branch-guard.sh): they
//     are delivered as `trackfw guard <name>` Go subcommands and run natively
//     on Windows without sh.
//   - Git hook scripts (.husky/pre-commit, .husky/commit-msg,
//     .lefthook/commit-msg/trackfw-req-check.sh): Git for Windows augments the
//     PATH before spawning every hook, adding usr\bin (where sh.exe lives).
//     All child processes of the hook — including the lefthook binary when
//     runner: sh is configured — inherit this augmented PATH and can find sh
//     even when it is absent from the user's interactive PATH.
//     Measured on Git for Windows 2.55.0 ARM64 (2026-11-17,
//     docs/portabilidade/2026-11-17-ml-4a-husky-sem-sh-no-path.md).
var shConvenienceArtifacts = []string{
	"scripts/trackfw-attention-signal.sh",
	"scripts/trackfw-attention-cleanup.sh",
	"scripts/trackfw-validate.sh",
}

// ShLookPathFn is exec.LookPath; exported so that tests in other packages
// (e.g., internal/commands) can inject a no-op to simulate sh absent.
var ShLookPathFn func(string) (string, error) = exec.LookPath

// validateWindowsShMissing is the entry point for the windows_sh_missing rule,
// consumed by both ValidateUnfiltered and validateUnfilteredTagged in validator.go.
func validateWindowsShMissing() []string {
	root, err := os.Getwd()
	if err != nil {
		return nil
	}
	return checkWindowsShMissing(CurrentGOOS, ShLookPathFn, root)
}

// CheckWindowsShMissingForDoctor is the exported entry point for
// internal/commands/doctor.go. It uses the same package-level seams
// (CurrentGOOS, ShLookPathFn) so doctor tests can inject "windows" and a
// no-op lookPath without duplicating the detection logic.
//
// Returns the POSIX-slash relative paths of .sh artifacts that are present in
// projectRoot when GOOS is "windows" and sh is absent from PATH; returns nil
// otherwise. The caller (doctor) converts each path into a DoctorFinding.
func CheckWindowsShMissingForDoctor(projectRoot string) []string {
	return windowsShMissingPaths(CurrentGOOS, ShLookPathFn, projectRoot)
}

// windowsShMissingPaths returns the POSIX-slash relative paths of .sh
// convenience artifacts that are present under projectRoot when goos is
// "windows" and sh is absent from PATH; returns nil otherwise.
// This is the shared detection core used by both validate and doctor paths.
func windowsShMissingPaths(goos string, lookPath func(string) (string, error), projectRoot string) []string {
	if goos != "windows" {
		return nil
	}
	if _, err := lookPath("sh"); err == nil {
		// sh is available — convenience scripts will execute without issue.
		return nil
	}
	var present []string
	for _, rel := range shConvenienceArtifacts {
		full := filepath.Join(projectRoot, filepath.FromSlash(rel))
		if _, statErr := os.Stat(full); statErr == nil {
			present = append(present, rel)
		}
	}
	return present // nil when empty; callers check len == 0
}

// checkWindowsShMissing is the injectable inner function used by the validate
// rule. goos and lookPath allow cross-platform testing.
//
// Returns nil when any of the following holds:
//   - goos != "windows"
//   - sh is found in PATH (lookPath("sh") succeeds)
//
// When GOOS is "windows" and sh is absent from PATH, always returns a
// single-element slice. The message always includes the phrase
// "sh not found in PATH — install a POSIX shell (e.g. Git Bash, WSL)"
// (aligned with barrier.go shMissingMsg) and cites that barrier gates using
// sh -c will not execute. When .sh convenience artifacts are present on disk,
// they are additionally listed in the message.
//
// REQ-IMP-9 (REQ-2026-11-15 ML-3D2): the rule fires even without artifacts
// because barrier gates (barrier.go:311,1462 — exec.Command("sh",...)) also
// fail when sh is absent from PATH.
func checkWindowsShMissing(goos string, lookPath func(string) (string, error), projectRoot string) []string {
	if goos != "windows" {
		return nil
	}
	if _, err := lookPath("sh"); err == nil {
		return nil
	}
	present := windowsShMissingPaths(goos, lookPath, projectRoot)
	if len(present) > 0 {
		return []string{fmt.Sprintf(
			"windows_sh_missing: sh not found in PATH — install a POSIX shell (e.g. Git Bash, WSL) "+
				"to evaluate gates and run .sh convenience scripts; "+
				"gates that use sh -c (trackfw barrier) will not execute; "+
				"the following scripts present in this project require sh to execute: %s",
			strings.Join(present, ", "),
		)}
	}
	// No .sh artifacts present, but barrier gates using sh -c will still fail.
	return []string{
		"windows_sh_missing: sh not found in PATH — install a POSIX shell (e.g. Git Bash, WSL) " +
			"to evaluate gates; gates that use sh -c (trackfw barrier) will not execute",
	}
}

// CheckWindowsShMissingBarrierForDoctor returns true when CurrentGOOS is
// "windows" and ShLookPathFn cannot find "sh" in PATH. The doctor uses this
// to emit a barrier-gates finding regardless of whether .sh artifacts are
// present — barrier.go:311,1462 fail without sh even in an empty project.
//
// REQ-IMP-9 (REQ-2026-11-15 ML-3D2).
func CheckWindowsShMissingBarrierForDoctor() bool {
	if CurrentGOOS != "windows" {
		return false
	}
	_, err := ShLookPathFn("sh")
	return err != nil
}
